608		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
609		signs. All the $\tau^X$ operators commute with one another, as do all the
610		$\tau^Z$ operators. Their common eigenbases consist of the vectors
611		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
612		\[
613			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
614			\omega^{-\tr(ej)} \ket{j}\;, \qquad
615			\ket{e_Z} = \ket{e}\;;
616		\]
617		the Fourier transform
618		\begin{equation}\label{eq:fourier-f}
619			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
620			\omega^{-\tr(ab)} \ket{a}\bra{b}
621		\end{equation}
622		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
623		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
624		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
625		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
626		\[
627			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
628			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
629		\]

710	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
711		\uses{def:generalized-pauli, def:subfield-trace}
712		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
713		% Paper equation label kept on the display it names.
714		\begin{equation}\label{eq:pauli-obs-proj}
715			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
716		\end{equation}
717		and conversely
718		\begin{equation}\label{eq:pauli-inversion-0}
719			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
720			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
721			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
722			= \tau^W_b\;.
723		\end{equation}
724		The source scope and the binary specialization of these identities are
725		recorded in \cite{gap:qpbt_characteristic-two-pauli-scope}.
726	\end{lemma}
727	\begin{proof}
728		\uses{def:generalized-pauli, lem:cancellation}
729		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
730		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
731		definition, and for $W = X$ it follows from the single-qudit computation
732		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
733		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
734		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
735		substitute the first display and exchange the order of summation; by
736		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
737		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
738		it equals $1$.
739	\end{proof}
740	
741	Since only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the
742	maximally entangled state $\ket{\mathrm{EPR}_q}$ and the qudit Pauli
743	projectors are isomorphic to tensor products of qubit EPR states
744	$\ket{\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the
745	next lemma, which is what allows the Pauli basis test to self-test Pauli
746	observables and maximally entangled states over \emph{qubits}

1101	The common eigenbasis for the $\qp^Z$ operators is the computational
1102	basis $\{\ket{j}\}_{j \in \F_q}$.
1103	To map this basis to the common eigenbasis of the $\qp^X$ operators, one can
1104	apply the Fourier transform
1105	\begin{equation}
1106	  \label{eq:fourier-f}
1107	  F \,=\, \frac{1}{\sqrt{q}} \sum_{a, b\in \Fq} \omega^{-\tr(ab)}
1108	  \ket{a}\bra{b}\;.
1109	\end{equation}
1110	Explicitly, the eigenbases consist of the vectors $\ket{e_W}$ labeled by an
1111	element $e \in \Fq$ and $W \in \{X, Z\}$, given by
1112	\begin{equation*}
1113	  \ket{e_X} = \frac{1}{\sqrt{q}} \sum_j \omega^{- \tr(e j)} \ket{j}\;, \qquad
1114	  \ket{e_Z}   = \ket{e}\;.
1115	\end{equation*}
1116	We denote the POVM whose elements are projectors onto basis vectors of the
1117	eigenbasis associated with the observables $\qp^W$ by $\{\qp^W_e\}_e$.
1118	Then for all $W \in \{X,Z\}$ and $a\in \Fq$, the observables $\qp^W(a)$ can be
1119	written as
1120	\begin{equation}\label{eq:pauli-obs-proj-single}
1121	  \qp^W(a) = \sum_{b \in \Fq} \omega^{\tr(a b)} \qp^W_b\;.
1122	\end{equation}
1123	
1124	To invert this relation, we first quote the following useful Fourier fact.
1125	\begin{lemma}[Fact 3.2 of \cite{NW19}]
1126	  \label{lem:cancellation}
1127	  Let $V$ be a subspace of $\F^k$. For all $v \not\in V^\perp$, 
1128	  \begin{equation*}
1129	    \E_{u \sim V} \omega^{\tr(u \cdot v)} = 0\;,
1130	  \end{equation*}
1131	  where the expectation is over a uniformly random vector $u$ from $V$.
1132	\end{lemma}
1133	
1134	We may now invert~\Cref{eq:pauli-obs-proj-single}:
1135	\begin{equation}\label{eq:pauli-inversion-0-single}
1136	  \E_{a\in \F_q} \omega^{-\tr(ab)} \qp^W(a) = \sum_{b'\in \F_q} \E_{a\in \F_q}
1137	  \omega^{\tr(a(b'-b))} \qp^W_{b'} = \qp^W_b\;,
1138	\end{equation}
1139	where the second step follows from Lemma~\ref{lem:cancellation}.
1140	
1141	For systems with many qudits, we will consider tensor products of the operators
1142	$\qp^W$.
1143	Slightly abusing notation, for $W \in \{X, Z\}$ and $a \in \Fq^n$ we denote by
1144	$\qp^W(a)$ the tensor product $\qp^W(a_1) \ot \dots \ot \qp^W(a_n)$.
1145	These obey the twisted commutation relations
1146	\begin{equation*}
1147	  \forall a,b\in \Fq^n,\qquad \qp^X(a)\, \qp^Z(b) \,=\, \omega^{-\tr (a \cdot
1148	    b)}\, \qp^Z(b)\, \qp^X(a)\;,
1149	\end{equation*}
1150	where $a \cdot b = \sum_{i=1}^{n} a_i b_i \in \Fq$.
1151	For $W\in\{X,Z\}$ and $e \in \Fq^n$ define the eigenstates
1152	\[ \ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}\;, \]
1153	and associated rank-$1$ projectors $\qp^W_e$. Analogous versions of \Cref{eq:pauli-obs-proj-single}
1154	and \Cref{eq:pauli-inversion-0-single} relate the multi-qubit observables
1155	and projectors:
1156	\begin{align}
1157	  \qp^W(a) &= \sum_{b \in \Fq^n} \omega^{\tr(a \cdot b)}
1158	  \qp^W_b\;, \label{eq:pauli-obs-proj} \\
1159	    \E_{a\in \F_q^n} \omega^{-\tr(a \cdot b)} \qp^W(a) &= \sum_{b'\in \F_q^n} \E_{a\in \F_q^n}
1160	  \omega^{\tr(a\cdot (b'-b))} \qp^W_{b'} = \qp^W_b\;. \label{eq:pauli-inversion-0}
1161	\end{align}
